const CACHE='glow-getter-v7';
const SHELL=['./','./index.html','./privacy.html','./style.css','./v2.css','./mobile-update.css','./v14.css','./app.js','./model.mjs','./community.mjs','./manifest.webmanifest','./fonts/Audiowide.ttf','./fonts/BricolageGrotesque.ttf','./goal-photos.png','./paisley-v2.png','./y2k-stickers.png','./playbook-route.png','./sidebar-books.png','./app-icon-192.png','./app-icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request).then(hit=>hit||caches.match('./index.html'))))});
